begin;

create or replace function public.update_compliance_breach(target_breach_id uuid,target_status text,target_root_cause text,target_remediation_plan text,target_owner_user_id uuid,target_date date)returns boolean language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());scoped public.compliance_breaches%rowtype;academy uuid;begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;select*into scoped from public.compliance_breaches where id=target_breach_id and status<>'closed'for update;if scoped.id is null or target_status not in('open','remediating','ready_for_review')or not exists(select 1 from public.platform_access where user_id=target_owner_user_id and status='active')then raise exception 'open breach, valid status, and active owner required' using errcode='23514';end if;select o.academy_id into academy from public.compliance_obligations o where o.id=scoped.obligation_id;update public.compliance_breaches set status=target_status,root_cause=nullif(btrim(coalesce(target_root_cause,'')),''),remediation_plan=btrim(target_remediation_plan),owner_user_id=target_owner_user_id,target_date=$6,updated_by=actor where id=scoped.id;perform public.write_audit_event(academy,'compliance.breach_'||target_status,'compliance_breach',scoped.id,'{}'::jsonb);return true;end;$$;

commit;
